<?php
declare(strict_types=1);
require __DIR__ . '/../api/config.php';
require __DIR__ . '/includes/storage.php';
$u=usuarioAtual(); if(!$u){header('Location: ../login.php');exit;}
function adminUser(array $u):bool{$p=strtolower((string)($u['perfil']??$u['role']??$u['nivel']??''));return !empty($u['is_admin'])||!empty($u['admin'])||$p==='admin'||strtolower((string)($u['login']??''))==='admin';}
if(!adminUser($u)){http_response_code(403);exit('Acesso restrito ao administrador.');}
$dir=orcamentosStorage(); if(!is_dir($dir))mkdir($dir,0775,true); $file=$dir.'/prestadores.json'; $sigDir=$dir.'/prestadores'; if(!is_dir($sigDir))mkdir($sigDir,0775,true);
$defaults=[['id'=>1,'nome'=>'Rogério Vieira de Brito','cpf'=>'323.634.328-19','telefone'=>'','endereco'=>'','assinatura'=>''],['id'=>2,'nome'=>'Marlon Macedo Ledis','cpf'=>'272.390.238-26','telefone'=>'','endereco'=>'','assinatura'=>''],['id'=>3,'nome'=>'Waldemar de Agostini Junior','cpf'=>'343.689.258-07','telefone'=>'','endereco'=>'','assinatura'=>'']];
$data=is_file($file)?json_decode((string)file_get_contents($file),true):null; if(!is_array($data)||!$data)$data=$defaults;
$csrf=csrfToken();$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  try{ $token=(string)($_POST['csrf_token']??'');if(!hash_equals((string)($_SESSION['csrf_token']??''),$token))throw new RuntimeException('Token de segurança inválido.');
    $action=(string)($_POST['action']??'save');
    if($action==='delete'){$id=(string)($_POST['id']??'');$data=array_values(array_filter($data,fn($p)=>(string)($p['id']??'')!==$id));}
    else{
      $id=(int)($_POST['id']??0);$id=$id>0?$id:(int)max(array_column($data,'id')?:[0])+1;
      $provider=['id'=>$id,'nome'=>trim((string)($_POST['nome']??'')),'cpf'=>trim((string)($_POST['cpf']??'')),'telefone'=>trim((string)($_POST['telefone']??'')),'endereco'=>trim((string)($_POST['endereco']??'')),'assinatura'=>''];
      if($provider['nome']===''||$provider['cpf']==='')throw new RuntimeException('Nome e CPF são obrigatórios.');
      foreach($data as &$p){if((int)($p['id']??0)===$id){$provider['assinatura']=$p['assinatura']??'';$p=$provider;break;}}unset($p);
      if(!array_filter($data,fn($p)=>(int)($p['id']??0)===$id))$data[]=$provider;
      $field='assinatura';if(isset($_FILES[$field])&&($_FILES[$field]['error']??1)===UPLOAD_ERR_OK){$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES[$field]['tmp_name']);$ext=$mime==='image/png'?'png':($mime==='image/jpeg'?'jpg':'');if($ext==='')throw new RuntimeException('A assinatura deve ser PNG ou JPG.');$dest=$sigDir.'/'.$id.'.'.$ext;foreach(glob($sigDir.'/'.$id.'.*')?:[] as $old){if($old!==$dest)@unlink($old);}copy($_FILES[$field]['tmp_name'],$dest);foreach($data as &$p){if((int)$p['id']===$id)$p['assinatura']=basename($dest);}unset($p);}
    }
    $settings=['signature_height'=>max(80,min(320,(int)($_POST['signature_height']??150))),'signature_gap'=>max(1,min(6,(int)($_POST['signature_gap']??1))),'signature_align'=>in_array($_POST['signature_align']??'left',['left','center','right'],true)?$_POST['signature_align']:'left'];
    file_put_contents($file,json_encode(array_values($data),JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT),LOCK_EX);file_put_contents($dir.'/config_gerador.json',json_encode($settings,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT),LOCK_EX);$msg='Cadastro atualizado com sucesso.';
  }catch(Throwable $e){$err=$e->getMessage();}
}
$settings=['signature_height'=>150,'signature_gap'=>1,'signature_align'=>'left'];$sf=$dir.'/config_gerador.json';if(is_file($sf)){$x=json_decode((string)file_get_contents($sf),true);if(is_array($x))$settings=array_merge($settings,$x);}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><?php $menuPage='prestadores'; ?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Prestadores</title><link rel="stylesheet" href="../assets/css/orcamentos/prestadores.css"></head><body><?php require __DIR__ . '/includes/nav.php'; ?><div class="wrap"><div class="page-title"><h1>Cadastro de Prestadores</h1><div class="muted">Nome, CPF, contato e assinatura reutilizável.</div></div><?php if($msg):?><div class="ok"><?=h($msg)?></div><?php endif;?><?php if($err):?><div class="err"><?=h($err)?></div><?php endif;?><div class="card"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=h($csrf)?>"><input type="hidden" name="action" value="save"><div class="grid"><div class="f"><label>Nome</label><input name="nome" required></div><div class="f"><label>CPF</label><input name="cpf" required></div><div class="f"><label>Telefone</label><input name="telefone"></div><div class="f"><label>Endereço</label><input name="endereco"></div></div><div class="grid" style="margin-top:10px"><div class="f"><label>ID (para editar)</label><input name="id" type="number" min="1"></div><div class="f"><label>Assinatura PNG/JPG</label><label class="file-picker file-picker-compact" for="assinatura"><input id="assinatura" name="assinatura" type="file" accept="image/png,image/jpeg"><span class="file-picker-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 16V4"/><path d="m7 9 5-5 5 5"/><path d="M5 20h14"/></svg></span><span class="file-picker-copy"><strong>Selecionar assinatura</strong><small>PNG ou JPG</small></span><span class="file-picker-arrow" aria-hidden="true">›</span></label></div><div class="f"><label>Altura padrão (px)</label><input name="signature_height" type="number" min="80" max="320" value="<?=h($settings['signature_height'])?>"></div><div class="f"><label>Espaço após TOTAL (linhas)</label><input name="signature_gap" type="number" min="1" max="6" value="<?=h($settings['signature_gap'])?>"></div></div><div class="grid" style="margin-top:10px"><div class="f"><label>Alinhamento</label><select name="signature_align"><option value="left" <?=($settings['signature_align']==='left'?'selected':'')?>>Esquerda</option><option value="center" <?=($settings['signature_align']==='center'?'selected':'')?>>Centro</option><option value="right" <?=($settings['signature_align']==='right'?'selected':'')?>>Direita</option></select></div></div><button class="btn" style="margin-top:12px">Salvar prestador</button></form></div><div class="card"><strong>Prestadores cadastrados</strong><?php foreach($data as $p):?><div class="provider"><div><b><?=h($p['nome'])?></b><div class="muted">ID <?=h($p['id'])?> · CPF <?=h($p['cpf'])?></div></div><div class="muted"><?=h($p['telefone'])?></div><div class="muted"><?=h($p['endereco'])?></div><div><?php if(!empty($p['assinatura'])):?><img class="sig" src="assinatura.php?id=<?=h($p['id'])?>&t=<?=time()?>"><?php else:?><span class="muted">Sem assinatura</span><?php endif;?></div><form method="post"><input type="hidden" name="csrf_token" value="<?=h($csrf)?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=h($p['id'])?>"><button class="btn gray" onclick="return confirm('Excluir este prestador?')">Excluir</button></form></div><?php endforeach;?></div></div></body></html>
